t filtering (Core > Filtered Post Types)'=>'%s: Ti muu ṣiṣẹ ifiwewe PressPermit (Core > Awọn Iru Ifiweranṣẹ Ti a Filter)','%1$s: Assigned extra %2$s Author role to %3$s role'=>'%1$s: Ti yan ipa %2$s ti o pọ si fun ipa %3$s','Ambiguous %1$s match (%2$s)'=>'Ibi %1$s ti ko ye (%2$s)','Ambiguous user match for %1$s (%2$s, post id %3$s'=>'Ipadabọ olumulo ti ko ye fun %1$s (%2$s, id ifiweranṣẹ %3$s','Ambiguous user match for %1$s (%2$s, $post id %3$s)'=>'Ipadabọ olumulo ti ko ye fun %1$s (%2$s, id ifiweranṣẹ $post %3$s)','Ambiguous user match for %1$s (%2$s)'=>'Ipadabọ olumulo ti ko ye fun %1$s (%2$s)','%1$s: %2$s posts created.'=>'%1$s: %2$s awọn ifiweranṣẹ ti a ṣẹda.','%1$s: %2$s posts updated.'=>'%1$s: %2$s awọn ifiweranṣẹ ti a ṣe imudojuiwọn.','All Roles'=>'Gbogbo Awọn ipa','%1$s: Done for %2$s.'=>'%1$s: Ti pari fun %2$s.','%s: Done.'=>'%s: Ti pari.']];